def solve(gi):
    gi=np.array(gi); H,W=gi.shape
    ys,xs=np.where((gi!=0)&(gi!=8))
    r0,c0=ys.min(),xs.min()
    K=gi[r0:ys.max()+1,xs.min():xs.max()+1]
    h,w=K.shape
    R=K[::-1,::-1]  # rot90cw
    out=gi.copy()
    for i in range(H):
