        y,x=st.pop(); cs.append((y,x))
        for dy in(-1,0,1):
            for dx in(-1,0,1):
                ny,nx=y+dy,x+dx
                if (ny,nx) not in seen and gi[ny,nx]==8:
                    seen.add((ny,nx)); st.append((ny,nx))
    cols=sorted(set(int(go[y,x]) for y,x in cs))
    ys=[y-r0 for y,_ in cs]; xs=[x-c0 for _,x in cs]
    print('rows',min(ys),'-',max(ys),'cols',min(xs),'-',max(xs),'colors',cols,'count',len(cs))

import numpy as np, os, re, json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
for nm in ['Demo pair 1','Demo pair 2']:
    gi=np.array(G[nm+' input']); go=np.array(G[nm+' output'])
    S=np.argwhere(gi==8); r0,r1,c0,c1=S[:,0].min(),S[:,0].max(),S[:,1].min(),S[:,1].max()
    Kc=np.argwhere((gi!=0)&(gi!=8))
    ky0,ky1,kx0,kx1=int(Kc[:,0].min()),int(Kc[:,0].max()),int(Kc[:,1].min()),int(Kc[:,1].max())
    KI=gi[ky0:ky1+1,kx0:kx1+1]; TH,TW=KI.shape
    print('===',nm,'key',TH,TW,'shape',r1-r0+1,c1-c0+1)
    # tile dims guess: tile_h = ? try tile_h = round? test exact tiling: shape must be multiple
    for rot in [2,3]:
        T=np.rot90(KI,rot)
        th,tw=T.shape
        if (r1-r0+1)%th==0 and (c1-c0+1)%tw==0:
            pred=np.copy(gi)
            for i in range(r1-r0+1-th+1):
                for j in range(c1-c0+1-tw+1):
                    pred[i:i+th,j:j+tw]=T
            print(' rot',rot,'exact tile fit:',(pred==go).all())
